// Validate the incoming webhook body and normalize.
// Expected payload:
// {
//   tenant_id: "...",
//   email: { from, subject, body, headers?, attachments? },
//   tenant_config: {
//     siteware_token: "<JWT>",
//     triage_model: "gpt-4.1",
//     reply_agent_id: "...",
//     tone_profile: { email_signature, knowledgebase }
//   }
// }

const body = $input.first().json.body || {};
const email = body.email || {};
const cfg = body.tenant_config || {};

const errors = [];
if (!body.tenant_id) errors.push("tenant_id missing");
if (!email.from) errors.push("email.from missing");
if (!email.subject) errors.push("email.subject missing");
if (!email.body) errors.push("email.body missing");
if (!cfg.siteware_token) errors.push("tenant_config.siteware_token missing");
if (!cfg.reply_agent_id) errors.push("tenant_config.reply_agent_id missing");

if (errors.length) {
  return [{ json: {
    __validation_failed: true,
    errors
  }}];
}

// Normalize and pass through
return [{ json: {
  tenant_id: body.tenant_id,
  from: email.from,
  subject: email.subject,
  body: String(email.body).substring(0, 5000),
  headers: email.headers || "",
  attachments: email.attachments || "",
  siteware_token: cfg.siteware_token,
  triage_model: cfg.triage_model || "gpt-4.1",
  reply_agent_id: cfg.reply_agent_id,
  tone_profile: {
    email_signature: (cfg.tone_profile && cfg.tone_profile.email_signature) || "",
    knowledgebase: (cfg.tone_profile && cfg.tone_profile.knowledgebase) || ""
  }
}}];

// Parse triage JSON from OpenAI passthrough response shape.
// Also carry forward the original context from Validate & Normalize so downstream nodes have tenant config + email.

const resp = $input.first().json;
const ctx = $('Validate & Normalize').first().json;

const texts = (resp.output || [])
  .flatMap(item => item.content || [])
  .filter(c => c.type === "output_text")
  .map(c => c.text);

const joined = texts.join("");
let clean = joined.trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");

let triage;
try {
  triage = JSON.parse(clean);
} catch (e) {
  return [{ json: {
    __parse_failed: true,
    stage: "triage_parse",
    raw: joined.slice(0, 500)
  }}];
}

return [{ json: {
  // Triage result
  classification: triage.classification,
  confidence: triage.confidence,
  reasoning: triage.reasoning,
  sentiment: triage.sentiment,
  escalation_triggered: triage.escalation_triggered,
  escalation_reason: triage.escalation_reason,
  language_detected: triage.language_detected,
  suggested_priority: triage.suggested_priority,
  // Carry forward context for downstream nodes
  tenant_id: ctx.tenant_id,
  from: ctx.from,
  subject: ctx.subject,
  body: ctx.body,
  headers: ctx.headers,
  attachments: ctx.attachments,
  siteware_token: ctx.siteware_token,
  reply_agent_id: ctx.reply_agent_id,
  tone_profile: ctx.tone_profile
}}];

