parameters.jsCode:
// Siteware agent responses come as { answer: "<JSON string>" }.
// Parse it out and merge with the triage context.

const resp = $input.first().json;
const ctx = $('Parse Triage').first().json;

const answer = resp.answer || "";
let clean = String(answer).trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");

let draft;
try {
  draft = JSON.parse(clean);
} catch (e) {
  // If it's not JSON, treat the whole answer as the reply body
  draft = { body_plain: answer };
}

return [{ json: {
  ok: true,
  tenant_id: ctx.tenant_id,
  classification: ctx.classification,
  confidence: ctx.confidence,
  reasoning: ctx.reasoning,
  sentiment: ctx.sentiment,
  escalation_triggered: ctx.escalation_triggered,
  escalation_reason: ctx.escalation_reason,
  language_detected: ctx.language_detected,
  suggested_priority: ctx.suggested_priority,
  email: {
    from: ctx.from,
    subject: ctx.subject,
    body: ctx.body
  },
  draft: {
    subject: draft.subject || ("Re: " + ctx.subject),
    body_plain: draft.body_plain || draft.body || draft.text || "",
    body_html: draft.body_html || null,
    placeholders: draft.placeholders || []
  }
}}];

// SPAM/AD path: no draft. Return classification only.
const ctx = $input.first().json;

return [{ json: {
  ok: true,
  tenant_id: ctx.tenant_id,
  classification: ctx.classification,
  confidence: ctx.confidence,
  reasoning: ctx.reasoning,
  sentiment: ctx.sentiment,
  escalation_triggered: ctx.escalation_triggered,
  escalation_reason: ctx.escalation_reason,
  language_detected: ctx.language_detected,
  suggested_priority: ctx.suggested_priority,
  email: {
    from: ctx.from,
    subject: ctx.subject,
    body: ctx.body
  },
  draft: null
}}];
